import numpy as np

def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_stock = 300.0  # OPT_PARAM: {"initial": 300.0, "min": 300.0, "max": 500.0, "type": "float"}
    demand_response = 0.8  # OPT_PARAM: {"initial": 0.8, "min": 0.8, "max": 1.2, "type": "float"}
    lead_time_adjustment = 8.0  # OPT_PARAM: {"initial": 8.0, "min": 8.0, "max": 12.0, "type": "float"}
    smoothing_factor = 0.15  # OPT_PARAM: {"initial": 0.15, "min": 0.15, "max": 0.25, "type": "float"}

    is_high_demand = last_demand >= 100.0 * np.log(2)
    adjusted_base = base_stock * (1.8 if is_high_demand else 1.0)
    target = adjusted_base + demand_response * last_demand + lead_time_adjustment * (quoted_lead_time - 6)
    current_pipeline = on_hand_inventory + sum(pipeline_orders)
    order_amount = max(0.0, (target - current_pipeline) * smoothing_factor)
    return order_amount

